'use client';

import * as React from 'react';
import { MessageCircle } from 'lucide-react';

import { cn } from '@/lib/utils';
import { SkeletonProvider } from '@/lib/skeleton-context';
import { Avatar, AvatarImage, AvatarFallback } from '@/components/ui/avatar';
import { Text } from '@/components/ui/text';
import { Image } from '@/components/ui/image';
import { Skeleton } from '@/components/ui/skeleton';
import { ReactionPills, REACTION_EMOJIS } from '@/components/feed/reaction-pills';
import { ReactionList } from '@/components/feed/reaction-list';
import { CommentsSection } from '@/components/feed/comments-section';
import { Card, CardContent, CardFooter, CardHeader } from '../ui/card';

// ============================================================================
// Constants
// ============================================================================

type ReactionEmoji = (typeof REACTION_EMOJIS)[number];

// ============================================================================
// Type Definitions
// ============================================================================

export interface PostCardAuthor {
    name: string;
    avatarUrl?: string;
    avatarFallback?: string;
}

export interface PostCardReaction {
    emoji: string;
    count: number;
}

export interface PostCardMedia {
    type: 'image' | 'video';
    url: string;
    alt?: string;
    width?: number;
    height?: number;
}

export interface PostCardActions {
    onReact?: (emoji: string) => void | Promise<void>;
    onUnreact?: () => void | Promise<void>;
    onCommentClick?: () => void | Promise<void>;
}

export interface PostCardProps {
    postId: string;
    author: PostCardAuthor;
    timestamp: string;
    content: string;
    media?: PostCardMedia[];
    reactions: PostCardReaction[];
    commentsCount: number;
    userReaction?: string | null;
    actions?: PostCardActions;
    skeletonLoading?: boolean;
    showComments?: boolean;
    currentUserAvatar?: string;
    currentUserName?: string;
    className?: string;
}

// ============================================================================
// Sub-components
// ============================================================================

interface IconButtonProps {
    onClick?: () => void;
    'aria-label': string;
    children: React.ReactNode;
}

function IconButton({ onClick, 'aria-label': ariaLabel, children }: IconButtonProps) {
    return (
        <button
            onClick={onClick}
            aria-label={ariaLabel}
            className="flex items-center justify-center size-8 rounded-full bg-black/5 border border-black/10 hover:bg-black/10 transition-colors"
        >
            {children}
        </button>
    );
}

interface MediaSectionProps {
    media: PostCardMedia[];
}

function MediaSection({ media }: MediaSectionProps) {
    if (!media || media.length === 0) {
        return null;
    }

    return (
        <div
            className={cn(
                'mt-4 grid gap-2',
                media.length === 1 && 'grid-cols-1',
                media.length === 2 && 'grid-cols-2',
                media.length >= 3 && 'grid-cols-2 md:grid-cols-3'
            )}
        >
            {media.map((item, index) => (
                <div key={index} className="relative overflow-hidden rounded-lg">
                    {item.type === 'image' ? (
                        <Image
                            src={item.url}
                            alt={item.alt || `Media ${index + 1}`}
                            width={item.width || 600}
                            height={item.height || 400}
                            className="w-full h-auto object-cover"
                        />
                    ) : (
                        <video
                            src={item.url}
                            controls
                            className="w-full h-auto"
                            aria-label={item.alt || `Video ${index + 1}`}
                        >
                            Your browser does not support the video tag.
                        </video>
                    )}
                </div>
            ))}
        </div>
    );
}

interface CommentsCountProps {
    count: number;
}

function CommentsCount({ count }: CommentsCountProps) {
    if (count === 0) {
        return null;
    }

    return (
        <Text className="text-sm text-foreground">
            {count} {count === 1 ? 'Comment' : 'Comments'}
        </Text>
    );
}

// ============================================================================
// Main Component
// ============================================================================

function PostCard({
    postId,
    author,
    timestamp,
    content,
    media,
    reactions,
    commentsCount,
    userReaction,
    actions,
    skeletonLoading = false,
    showComments = false,
    currentUserAvatar,
    currentUserName,
    className,
}: PostCardProps) {
    const [isCommentsOpen, setIsCommentsOpen] = React.useState(showComments);
    const [isReactionListOpen, setIsReactionListOpen] = React.useState(false);

    const handleCommentClick = React.useCallback(() => {
        setIsCommentsOpen((prev) => !prev);
        actions?.onCommentClick?.();
    }, [actions]);

    const handleReact = React.useCallback(
        (emoji: string) => {
            actions?.onReact?.(emoji);
        },
        [actions]
    );

    const handleUnreact = React.useCallback(() => {
        actions?.onUnreact?.();
    }, [actions]);

    const handleOpenReactionList = React.useCallback(() => {
        setIsReactionListOpen(true);
    }, []);

    const handleCloseReactionList = React.useCallback(() => {
        setIsReactionListOpen(false);
    }, []);

    const totalReactionCount = reactions.reduce((sum, r) => sum + r.count, 0);

    return (
        <SkeletonProvider loading={skeletonLoading}>
            <Card
                className={cn(
                    'w-full bg-white border border-[#eae7ec] rounded-3xl overflow-hidden',
                    className
                )}
            >
                {/* Profile Header */}
                <CardHeader className="flex items-start gap-2 p-3">
                    <Avatar className="size-12 shrink-0">
                        <AvatarImage src={author.avatarUrl} alt={author.name} />
                        <AvatarFallback>
                            {author.avatarFallback ||
                                author.name
                                    .split(' ')
                                    .map((n) => n[0])
                                    .join('')
                                    .toUpperCase()
                                    .slice(0, 2)}
                        </AvatarFallback>
                    </Avatar>
                    <div className="flex flex-col justify-center gap-1 min-h-12">
                        <Text
                            as="span"
                            className="text-base font-semibold text-foreground leading-6"
                        >
                            {author.name}
                        </Text>
                        <Text as="span" className="text-xs text-foreground/60 leading-4">
                            {timestamp}
                        </Text>
                    </div>
                </CardHeader>

                {/* Content */}
                <CardContent className="px-4 pb-4">
                    {skeletonLoading ? (
                        <div className="space-y-2">
                            <Skeleton variant="text" className="w-full" />
                            <Skeleton variant="text" className="w-full" />
                            <Skeleton variant="text" className="w-3/4" />
                        </div>
                    ) : (
                        <Text
                            as="p"
                            className="text-sm leading-5 text-foreground whitespace-pre-wrap break-words"
                        >
                            {content}
                        </Text>
                    )}
                    {media && media.length > 0 && <MediaSection media={media} />}
                </CardContent>

                {/* Activity Bar */}
                <CardFooter className="flex items-center justify-between px-4 py-3">
                    <div className="flex items-center gap-1">
                        <ReactionPills
                            reactions={reactions}
                            userReaction={userReaction}
                            totalCount={totalReactionCount}
                            onReact={handleReact}
                            onUnreact={handleUnreact}
                            onOpenReactionList={handleOpenReactionList}
                        />
                        <IconButton onClick={handleCommentClick} aria-label="View comments">
                            <MessageCircle className="size-5 text-foreground" />
                        </IconButton>
                    </div>
                    <CommentsCount count={commentsCount} />
                </CardFooter>

                {/* Comments Section */}
                {isCommentsOpen && (
                    <div className="border-t border-[#eae7ec]">
                        <CommentsSection
                            postId={postId}
                            currentUserAvatar={currentUserAvatar}
                            currentUserName={currentUserName}
                        />
                    </div>
                )}
            </Card>

            {/* Reaction List Modal */}
            <ReactionList
                postId={postId}
                isOpen={isReactionListOpen}
                onClose={handleCloseReactionList}
            />
        </SkeletonProvider>
    );
}

export { PostCard };
export type { ReactionEmoji };
