// ============================================================================
// Hooks
// ============================================================================

interface UseCommentsOptions {
  enabled?: boolean;
}

export function useComments(postId: string, options: UseCommentsOptions = {}) {
  const { enabled = true } = options;

  return useQuery({
    queryKey: queryKeys.comments.list(postId),
    queryFn: () => fetchComments(postId),
    enabled: enabled && !!postId,
    staleTime: 30 * 1000, // 30 seconds
  });
}

interface AddCommentVariables {
  postId: string;
  content: string;
  parentId?: string;
}

export function useAddComment() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ postId, content, parentId }: AddCommentVariables) =>
      addCommentApi(postId, content, parentId),
    onMutate: async ({ postId, content, parentId }) => {
      // Cancel outgoing refetches
      await queryClient.cancelQueries({
        queryKey: queryKeys.comments.list(postId),
      });

      // Snapshot previous value
      const previousData = queryClient.getQueryData<CommentsResponse>(
        queryKeys.comments.list(postId)
      );

      // Optimistically add the comment
      const optimisticComment: Comment = {
        id: `temp-${Date.now()}`,
        author: {
          id: 'current-user',
          name: 'You',
          avatarUrl: 'https://i.pravatar.cc/150?u=current',
        },
        content,
        timestamp: 'Just now',
        likesCount: 0,
        isLiked: false,
        repliesCount: 0,
      };

      queryClient.setQueryData<CommentsResponse>(
        queryKeys.comments.list(postId),
        (old) => {
          if (!old) return old;

          if (parentId) {
            // Add as reply
            const updatedComments = old.comments.map((comment) => {
              if (comment.id === parentId) {
                return {
                  ...comment,
                  repliesCount: comment.repliesCount + 1,
                  replies: [...(comment.replies || []), optimisticComment],
                };
              }
              return comment;
            });
            return { ...old, comments: updatedComments };
          }

          // Add as top-level comment
          return {
            ...old,
            comments: [...old.comments, optimisticComment],
            totalCount: old.totalCount + 1,
          };
        }
      );

      return { previousData };
    },
    onError: (_err, { postId }, context) => {
      // Rollback on error
      if (context?.previousData) {
        queryClient.setQueryData(
          queryKeys.comments.list(postId),
          context.previousData
        );
      }
    },
    onSettled: (_data, _error, { postId }) => {
      // Refetch after mutation
      queryClient.invalidateQueries({
        queryKey: queryKeys.comments.list(postId),
      });
    },
  });
}

interface LikeCommentVariables {
  postId: string;
  commentId: string;
  isLiked: boolean;
}

export function useLikeComment() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ commentId, isLiked }: LikeCommentVariables) =>
      likeCommentApi(commentId, isLiked),
    onMutate: async ({ postId, commentId, isLiked }) => {
      await queryClient.cancelQueries({
        queryKey: queryKeys.comments.list(postId),
      });

      const previousData = queryClient.getQueryData<CommentsResponse>(
        queryKeys.comments.list(postId)
      );

      // Helper to update comment likes recursively
      const updateCommentLikes = (comments: Comment[]): Comment[] => {
        return comments.map((comment) => {
          if (comment.id === commentId) {
            return {
              ...comment,
              isLiked,
              likesCount: isLiked
                ? comment.likesCount + 1
                : Math.max(0, comment.likesCount - 1),
            };
          }
          if (comment.replies) {
            return {
              ...comment,
              replies: updateCommentLikes(comment.replies),
            };
          }
          return comment;
        });
      };

      queryClient.setQueryData<CommentsResponse>(
        queryKeys.comments.list(postId),
        (old) => {
          if (!old) return old;
          return {
            ...old,
            comments: updateCommentLikes(old.comments),
          };
        }
      );

      return { previousData };
    },
    onError: (_err, { postId }, context) => {
      if (context?.previousData) {
        queryClient.setQueryData(
          queryKeys.comments.list(postId),
          context.previousData
        );
      }
    },
  });
}
