'use client';

import * as React from 'react';
import { ArrowUp } from 'lucide-react';

import { cn } from '@/lib/utils';
import { Avatar, AvatarImage, AvatarFallback } from '@/components/ui/avatar';
import { Text } from '@/components/ui/text';
import { Skeleton } from '@/components/ui/skeleton';
import { CommentItem } from '@/components/feed/comment-item';
import { useComments, useAddComment, useLikeComment } from '@/hooks/use-comments';

// ============================================================================
// Type Definitions
// ============================================================================

export interface CommentsSectionProps {
  postId: string;
  currentUserAvatar?: string;
  currentUserName?: string;
  className?: string;
}

// ============================================================================
// Sub-components
// ============================================================================

interface CommentInputProps {
  avatarUrl?: string;
  avatarFallback?: string;
  onSubmit: (content: string) => void;
  isSubmitting?: boolean;
  placeholder?: string;
  autoFocus?: boolean;
}

function CommentInput({
  avatarUrl,
  avatarFallback = 'U',
  onSubmit,
  isSubmitting = false,
  placeholder = 'Join the conversation...',
  autoFocus = false,
}: CommentInputProps) {
  const [value, setValue] = React.useState('');
  const inputRef = React.useRef<HTMLInputElement>(null);

  const handleSubmit = React.useCallback(() => {
    const trimmed = value.trim();
    if (!trimmed || isSubmitting) return;
    onSubmit(trimmed);
    setValue('');
  }, [value, isSubmitting, onSubmit]);

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        handleSubmit();
      }
    },
    [handleSubmit]
  );

  React.useEffect(() => {
    if (autoFocus && inputRef.current) {
      inputRef.current.focus();
    }
  }, [autoFocus]);

  return (
    <div className="flex items-center gap-2 w-full">
      <Avatar className="size-8 shrink-0">
        <AvatarImage src={avatarUrl} alt="Your avatar" />
        <AvatarFallback>{avatarFallback}</AvatarFallback>
      </Avatar>

      <div className="flex-1 flex items-center h-12 bg-white/90 border border-foreground/15 rounded-full px-1 py-0">
        <input
          ref={inputRef}
          type="text"
          value={value}
          onChange={(e) => setValue(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          disabled={isSubmitting}
          className="flex-1 h-full px-3 bg-transparent text-base text-foreground placeholder:text-foreground/40 outline-none"
        />

        <button
          onClick={handleSubmit}
          disabled={!value.trim() || isSubmitting}
          className={cn(
            'flex items-center justify-center size-10 rounded-full transition-colors',
            'bg-foreground/5 hover:bg-foreground/10',
            'disabled:opacity-50 disabled:cursor-not-allowed'
          )}
          aria-label="Send comment"
        >
          <ArrowUp className="size-6 text-foreground" />
        </button>
      </div>
    </div>
  );
}

interface LoadMoreButtonProps {
  onClick: () => void;
  isLoading?: boolean;
}

function LoadMoreButton({ onClick, isLoading }: LoadMoreButtonProps) {
  return (
    <button
      onClick={onClick}
      disabled={isLoading}
      className={cn(
        'flex items-center justify-center h-10 px-4',
        'border border-foreground/20 rounded-full',
        'text-base font-medium text-foreground',
        'hover:bg-foreground/5 transition-colors',
        'disabled:opacity-50 disabled:cursor-not-allowed'
      )}
    >
      {isLoading ? 'Loading...' : 'Load more comments'}
    </button>
  );
}

function CommentsSkeleton() {
  return (
    <div className="flex flex-col gap-3">
      {[1, 2].map((i) => (
        <div key={i} className="flex gap-2">
          <Skeleton variant="avatar" className="size-8" />
          <div className="flex-1 flex flex-col gap-2">
            <Skeleton variant="text" className="w-32" />
            <Skeleton variant="text" className="w-full" />
            <Skeleton variant="text" className="w-16" />
          </div>
        </div>
      ))}
    </div>
  );
}

// ============================================================================
// Main Component
// ============================================================================

function CommentsSection({
  postId,
  currentUserAvatar,
  currentUserName,
  className,
}: CommentsSectionProps) {
  const [replyingTo, setReplyingTo] = React.useState<string | null>(null);

  const { data, isLoading, isError } = useComments(postId);
  const addComment = useAddComment();
  const likeComment = useLikeComment();

  const handleAddComment = React.useCallback(
    (content: string) => {
      addComment.mutate({
        postId,
        content,
        parentId: replyingTo || undefined,
      });
      setReplyingTo(null);
    },
    [postId, replyingTo, addComment]
  );

  const handleReply = React.useCallback((commentId: string) => {
    setReplyingTo(commentId);
  }, []);

  const handleLike = React.useCallback(
    (commentId: string, isLiked: boolean) => {
      likeComment.mutate({ postId, commentId, isLiked });
    },
    [postId, likeComment]
  );

  const handleLoadMore = React.useCallback(() => {
    // TODO: Implement pagination when API supports it
  }, []);

  const comments = data?.comments || [];
  const hasMore = data?.hasMore || false;

  return (
    <div className={cn('flex flex-col w-full', className)}>
      {/* Comment Input */}
      <div className="px-4 py-4">
        <CommentInput
          avatarUrl={currentUserAvatar}
          avatarFallback={
            currentUserName
              ?.split(' ')
              .map((n) => n[0])
              .join('')
              .toUpperCase()
              .slice(0, 2) || 'U'
          }
          onSubmit={handleAddComment}
          isSubmitting={addComment.isPending}
          placeholder={
            replyingTo ? 'Write a reply...' : 'Join the conversation...'
          }
        />
        {replyingTo && (
          <button
            onClick={() => setReplyingTo(null)}
            className="mt-2 text-sm text-foreground/60 hover:text-foreground"
          >
            Cancel reply
          </button>
        )}
      </div>

      {/* Comments List */}
      <div className="flex flex-col gap-3 px-4 pb-4">
        {isLoading ? (
          <CommentsSkeleton />
        ) : isError ? (
          <Text className="text-sm text-red-500">Failed to load comments</Text>
        ) : comments.length === 0 ? (
          <Text className="text-sm text-foreground/60">
            No comments yet. Be the first to comment!
          </Text>
        ) : (
          <>
            {comments.map((comment) => (
              <CommentItem
                key={comment.id}
                comment={comment}
                onReply={handleReply}
                onLike={handleLike}
              />
            ))}

            {/* Load More */}
            {hasMore && (
              <div className="pt-4">
                <LoadMoreButton onClick={handleLoadMore} />
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

export { CommentsSection };
