'use client';

import * as React from 'react';
import { X } from 'lucide-react';

import { cn } from '@/lib/utils';
import { Avatar, AvatarImage, AvatarFallback } from '@/components/ui/avatar';
import { Text } from '@/components/ui/text';
import { Skeleton } from '@/components/ui/skeleton';
import {
  useReactionList,
  filterReactionsByEmoji,
} from '@/hooks/use-reactions';
import type { ReactionUser } from '@/types/api';

// ============================================================================
// Type Definitions
// ============================================================================

export interface ReactionListProps {
  postId: string;
  isOpen: boolean;
  onClose: () => void;
}

// ============================================================================
// Sub-components
// ============================================================================

interface TabButtonProps {
  label: string;
  emoji?: string;
  count: number;
  isActive: boolean;
  onClick: () => void;
}

function TabButton({ label, emoji, count, isActive, onClick }: TabButtonProps) {
  return (
    <button
      onClick={onClick}
      className={cn(
        'flex items-center gap-1 h-9 px-3 rounded-full transition-colors whitespace-nowrap',
        isActive
          ? 'bg-foreground text-white'
          : 'bg-transparent text-foreground hover:bg-foreground/5'
      )}
      aria-pressed={isActive}
    >
      {emoji && <span className="text-2xl leading-none">{emoji}</span>}
      <Text className={cn('text-base font-medium', isActive && 'text-white')}>
        {emoji ? count : label}
      </Text>
    </button>
  );
}

interface ReactionUserRowProps {
  user: ReactionUser;
}

function ReactionUserRow({ user }: ReactionUserRowProps) {
  return (
    <div className="flex items-center gap-3 w-full">
      <Avatar className="size-10 shrink-0">
        <AvatarImage src={user.userAvatar} alt={user.userName} />
        <AvatarFallback>
          {user.userName
            .split(' ')
            .map((n) => n[0])
            .join('')
            .toUpperCase()
            .slice(0, 2)}
        </AvatarFallback>
      </Avatar>

      <Text className="flex-1 text-sm font-medium text-foreground truncate">
        {user.userName}
      </Text>

      <Text className="text-[28px] leading-9">{user.emoji}</Text>
    </div>
  );
}

function ReactionListSkeleton() {
  return (
    <div className="flex flex-col gap-3">
      {[1, 2, 3, 4].map((i) => (
        <div key={i} className="flex items-center gap-3">
          <Skeleton variant="avatar" className="size-10" />
          <Skeleton variant="text" className="flex-1 h-5" />
          <Skeleton variant="text" className="w-8 h-8" />
        </div>
      ))}
    </div>
  );
}

// ============================================================================
// Main Component
// ============================================================================

function ReactionList({ postId, isOpen, onClose }: ReactionListProps) {
  const [selectedEmoji, setSelectedEmoji] = React.useState<string | null>(null);
  const modalRef = React.useRef<HTMLDivElement>(null);

  const { data, isLoading } = useReactionList(postId, { enabled: isOpen });

  // Handle click outside
  React.useEffect(() => {
    if (!isOpen) return;

    function handleClickOutside(event: MouseEvent) {
      if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
        onClose();
      }
    }

    function handleEscape(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        onClose();
      }
    }

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEscape);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEscape);
    };
  }, [isOpen, onClose]);

  // Prevent body scroll when modal is open
  React.useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }

    return () => {
      document.body.style.overflow = '';
    };
  }, [isOpen]);

  // Reset filter when modal closes
  React.useEffect(() => {
    if (!isOpen) {
      setSelectedEmoji(null);
    }
  }, [isOpen]);

  React.useEffect(() => {
    console.log('reactions: ', data)
  }, [data])

  if (!isOpen) return null;

  const reactions = data?.reactions || [];
  const summary = data?.summary || [];
  const totalCount = data?.totalCount || 0;
  const filteredReactions = filterReactionsByEmoji(reactions, selectedEmoji);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50">
      <div
        ref={modalRef}
        className={cn(
          'flex flex-col w-full max-w-md max-h-[80vh] bg-white rounded-3xl overflow-hidden',
          'border border-foreground/5',
          'animate-in fade-in zoom-in-95 duration-200'
        )}
        role="dialog"
        aria-modal="true"
        aria-labelledby="reaction-list-title"
      >
        {/* Header */}
        <div className="flex flex-col gap-4 pt-4">
          <div className="flex items-center justify-between px-4">
            <Text
              id="reaction-list-title"
              className="text-xl font-semibold text-foreground"
            >
              Reactions
            </Text>

            <button
              onClick={onClose}
              className="flex items-center justify-center size-8 rounded hover:bg-foreground/5 transition-colors"
              aria-label="Close"
            >
              <X className="size-6 text-foreground" />
            </button>
          </div>

          {/* Tabs */}
          <div className="flex items-center gap-1 px-3 pb-2 overflow-x-auto scrollbar-hide">
            <TabButton
              label={`All ${totalCount}`}
              count={totalCount}
              isActive={selectedEmoji === null}
              onClick={() => setSelectedEmoji(null)}
            />
            {summary.map((s) => (
              <TabButton
                key={s.emoji}
                emoji={s.emoji}
                label=""
                count={s.count}
                isActive={selectedEmoji === s.emoji}
                onClick={() => setSelectedEmoji(s.emoji)}
              />
            ))}
          </div>
        </div>

        {/* User List */}
        <div className="flex-1 overflow-y-auto bg-neutral-50 border-t border-neutral-200 px-4 pt-3 pb-4">
          {isLoading ? (
            <ReactionListSkeleton />
          ) : filteredReactions.length === 0 ? (
            <Text className="text-sm text-foreground/60">No reactions yet</Text>
          ) : (
            <div className="flex flex-col gap-3">
              {filteredReactions.map((user) => (
                <ReactionUserRow key={user.userId} user={user} />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export { ReactionList };
